/**
 * @file    server.c
 * @brief   e_server reference C backend (host-side).
 *
 * A minimal single-page web server that mirrors the API the STM32F429-origin
 * board's embedded server will implement. It serves the gzipped, CSS/JS
 * inlined page (from web_assets.h, generated by build_web.py) and three JSON
 * endpoints:
 *
 *   GET  /             gzip page (Content-Encoding: gzip)
 *   GET  /api/leds     {"leds":[0,0]}
 *   POST /api/leds     body {"leds":[0,0]} -> applied, {"leds":[0,0]}
 *   GET  /api/adc      {"vrefint_mv":..,"temp_c":..,"vbat_v":..,"dht11_t":..,"dht11_h":..,"ts":..}
 *   GET  /api/info     {"arch","lan_ip","public_ip","geo","weather","ts"}
 *   GET  /public/<name>  raw image bytes (from the embedded_files[] table)
 *
 * The /api/info external lookups (public IP via api.ipify.org, geo via
 * ip-api.com, weather via wttr.in) are best-effort plain-HTTP fetches; any
 * failure yields JSON nulls and the page shows "N/A". On the board these
 * would be implemented with an HTTP client (+TLS for HTTPS upstreams).
 *
 * Build:  python build_web.py && gcc -O2 -o e_server server.c
 *         (Windows/MinGW adds -lws2_32)
 * Run:    ./e_server [port]      default 8080
 */

